class Solution { public: string reformatDate(string date){stringstream stream(date);string dayToken,monthToken,year;stream>>dayToken>>monthToken>>year;vector<string> months={"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};int day=stoi(dayToken),month=find(months.begin(),months.end(),monthToken)-months.begin()+1;char buffer[11];snprintf(buffer,sizeof(buffer),"%04d-%02d-%02d",stoi(year),month,day);return buffer;} };
